def listRepositories(owner=None, name=None, visibility=None, status=None, page=None, pageSize=None, sort=None, order=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0127000" if __import__("os").path.isdir("./environment_mix/0127000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # validate
    if owner is not None and (not isinstance(owner, str) or not owner.strip()):
        return _err("VALIDATION_ERROR", "owner must be a non-empty string when provided")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")

    # tool enums include 'internal', but schema stores 'unknown' for some; reject invalid filters per tool contract
    if visibility is not None:
        if not isinstance(visibility, str):
            return _err("VALIDATION_ERROR", "visibility must be a string when provided")
        if visibility not in ("public", "private", "internal"):
            return _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string when provided")
        if status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200")
    if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "owner", "name"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, owner, name")
    if not isinstance(order, str) or order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    repos = _load("repositories.json")

    # apply filters
    out = []
    for r in repos:
        if owner is not None and r.get("owner") != owner.strip():
            continue
        if name is not None and r.get("name") != name.strip():
            continue
        if visibility is not None and r.get("visibility") != visibility:
            continue
        if status is not None and r.get("status") != status:
            continue
        out.append(r)

    reverse = (order == "desc")
    def _k(r):
        v = r.get(sort)
        return "" if v is None else v
    out.sort(key=_k, reverse=reverse)

    total = len(out)
    start = (page - 1) * pageSize
    end = start + pageSize
    items = out[start:end]
    has_more = end < total

    return {
        "items": items,
        "page": page,
        "pageSize": pageSize,
        "total": total,
        "has_more": has_more
    }

def getRepository(repositoryId, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0127000" if __import__("os").path.isdir("./environment_mix/0127000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(repositoryId, str) or not repositoryId.strip():
        return _err("VALIDATION_ERROR", "repositoryId must be a non-empty string")

    repos = _load("repositories.json")
    rid = repositoryId.strip()
    for r in repos:
        if r.get("id") == rid:
            return {"repository": r}
    return _err("NOT_FOUND", "Repository not found", repositoryId=rid)

def updateRepository(repositoryId, status=None, defaultBranch=None, visibility=None, htmlUrl=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0127000" if __import__("os").path.isdir("./environment_mix/0127000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(repositoryId, str) or not repositoryId.strip():
        return _err("VALIDATION_ERROR", "repositoryId must be a non-empty string")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled, deleted")
    if defaultBranch is not None and (not isinstance(defaultBranch, str) or not defaultBranch.strip()):
        return _err("VALIDATION_ERROR", "defaultBranch must be a non-empty string when provided")
    if visibility is not None:
        if not isinstance(visibility, str) or visibility not in ("public", "private", "internal"):
            return _err("VALIDATION_ERROR", "visibility must be one of: public, private, internal")
    if htmlUrl is not None and (not isinstance(htmlUrl, str) or not htmlUrl.strip()):
        return _err("VALIDATION_ERROR", "htmlUrl must be a non-empty string when provided")

    repos = _load("repositories.json")
    rid = repositoryId.strip()
    idx = None
    for i, r in enumerate(repos):
        if r.get("id") == rid:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Repository not found", repositoryId=rid)

    r = repos[idx]

    # Refuse attempts to serve deleted repositories: updates to deleted are invalid transitions unless staying deleted (no-op)
    if r.get("status") == "deleted":
        # Any mutation request that would change anything should be refused
        if status is None or status == "deleted":
            # still allow updating other fields? business rule says refuse attempts to serve deleted; for update, refuse mutations.
            if defaultBranch is None and visibility is None and htmlUrl is None and status is None:
                return _err("VALIDATION_ERROR", "No fields to update")
            return _err("INVALID_TRANSITION", "Cannot update a deleted repository")
        return _err("INVALID_TRANSITION", "Cannot transition from deleted to another status")

    mutated = False
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # status transition
    if status is not None and status != r.get("status"):
        allowed = {
            "active": {"disabled", "deleted"},
            "disabled": {"active", "deleted"},
            "deleted": set(),
        }
        cur = r.get("status")
        if status not in allowed.get(cur, set()):
            return _err("INVALID_TRANSITION", f"Invalid status transition: {cur} -> {status}")
        r["status"] = status
        mutated = True

    # mutable fields
    if defaultBranch is not None and defaultBranch.strip() != (r.get("default_branch") or ""):
        r["default_branch"] = defaultBranch.strip()
        mutated = True
    if visibility is not None and visibility != r.get("visibility"):
        r["visibility"] = visibility
        mutated = True
    if htmlUrl is not None and htmlUrl.strip() != (r.get("html_url") or ""):
        r["html_url"] = htmlUrl.strip()
        mutated = True

    if not mutated:
        return _err("VALIDATION_ERROR", "No changes to apply")

    r["updated_at"] = now
    repos[idx] = r
    _save("repositories.json", repos)

    return {"repository": r}

def listRepoSnapshots(repositoryId, branch=None, headSha=None, status=None, source=None, page=None, pageSize=None, sort=None, order=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0127000" if __import__("os").path.isdir("./environment_mix/0127000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    endpoint = "listRepoSnapshots"

    # ---- helpers ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status_code, message=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = datetime.datetime.utcnow() - t0
        latency_ms = int(dt.total_seconds() * 1000)
        row = {
            "id": f"rl_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "message": message,
        }
        if extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_str(name, v, allow_empty=False):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string")
        if not allow_empty and v.strip() == "":
            return _err("VALIDATION_ERROR", f"{name} must not be empty")
        return None

    def _validate_int(name, v, mn=None, mx=None):
        if v is None:
            return None
        if not isinstance(v, int):
            return _err("VALIDATION_ERROR", f"{name} must be an integer")
        if mn is not None and v < mn:
            return _err("VALIDATION_ERROR", f"{name} must be >= {mn}")
        if mx is not None and v > mx:
            return _err("VALIDATION_ERROR", f"{name} must be <= {mx}")
        return None

    # ---- input validation ----
    e = _validate_str("repositoryId", repositoryId)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    e = _validate_str("branch", branch)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    e = _validate_str("headSha", headSha)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    if status is not None:
        if not isinstance(status, str):
            e = _err("VALIDATION_ERROR", "status must be a string")
            _log_call("VALIDATION_ERROR", e["error"]["message"])
            return e
        if status not in ["queued", "building", "ready", "failed", "expired"]:
            e = _err("VALIDATION_ERROR", "status must be one of: queued, building, ready, failed, expired")
            _log_call("VALIDATION_ERROR", e["error"]["message"])
            return e
    if source is not None:
        if not isinstance(source, str):
            e = _err("VALIDATION_ERROR", "source must be a string")
            _log_call("VALIDATION_ERROR", e["error"]["message"])
            return e
        if source not in ["github", "cache", "unknown"]:
            e = _err("VALIDATION_ERROR", "source must be one of: github, cache, unknown")
            _log_call("VALIDATION_ERROR", e["error"]["message"])
            return e

    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 50
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    e = _validate_int("page", page, mn=1)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    e = _validate_int("pageSize", pageSize, mn=1, mx=200)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    if sort not in ["created_at", "updated_at"]:
        e = _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at")
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    if order not in ["asc", "desc"]:
        e = _err("VALIDATION_ERROR", "order must be one of: asc, desc")
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e

    # ---- resolve repository ----
    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []
    repo_row = None
    for r in repos:
        if isinstance(r, dict) and r.get("id") == repositoryId:
            repo_row = r
            break
    if repo_row is None:
        _log_call("NOT_FOUND", "Repository not found", repositoryId=repositoryId)
        return _err("NOT_FOUND", "Repository not found", repositoryId=repositoryId)

    # repository lifecycle serving constraint (reads should refuse serving disabled/deleted)
    if repo_row.get("status") in ["disabled", "deleted"]:
        _log_call("UNAUTHORIZED", "Repository is not available", repositoryId=repositoryId, repo_status=repo_row.get("status"))
        return _err("UNAUTHORIZED", "Repository is not available", repositoryId=repositoryId)

    snaps = _load("repo_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    # ---- filter mapping: tool source -> stored source ----
    # Stored enum: github_api, github_archive, unknown. Tool enum: github, cache, unknown.
    def _source_matches(stored, tool_val):
        if tool_val is None:
            return True
        if tool_val == "unknown":
            return stored == "unknown"
        if tool_val == "github":
            return stored in ["github_api", "github_archive"]
        if tool_val == "cache":
            # no explicit cache source in schema; treat none as matching
            return False
        return False

    out = []
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") != repositoryId:
            continue
        if branch is not None and s.get("branch") != branch:
            continue
        if headSha is not None and s.get("head_sha") != headSha:
            continue
        if status is not None and s.get("status") != status:
            continue
        if not _source_matches(s.get("source"), source):
            continue
        out.append(s)

    reverse = (order == "desc")
    def _sort_key(x):
        v = x.get(sort)
        if isinstance(v, str):
            return v
        return ""
    out.sort(key=_sort_key, reverse=reverse)

    total = len(out)
    start = (page - 1) * pageSize
    end = start + pageSize
    items = out[start:end]
    has_more = end < total
    next_cursor = None
    if has_more:
        next_cursor = str(page + 1)

    resp = {
        "snapshots": items,
        "page": page,
        "page_size": pageSize,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order,
    }
    _log_call("OK", repositoryId=repositoryId, returned=len(items), total=total)
    return resp

def createRepoSnapshot(repositoryId, branch=None, headSha=None, source=None, forceRebuild=None, **_extra):
    import json, os, datetime, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0127000" if __import__("os").path.isdir("./environment_mix/0127000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    endpoint = "createRepoSnapshot"

    # ---- helpers ----
    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_call(status_code, message=None, **extra):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        dt = datetime.datetime.utcnow() - t0
        latency_ms = int(dt.total_seconds() * 1000)
        row = {
            "id": f"rl_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "ts": _now_iso(),
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": latency_ms,
            "message": message,
        }
        if extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{''.join(random.choice(string.ascii_lowercase+string.digits) for _ in range(6))}"

    def _validate_str(name, v, allow_empty=False):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{name} must be a string")
        if not allow_empty and v.strip() == "":
            return _err("VALIDATION_ERROR", f"{name} must not be empty")
        return None

    # ---- input validation ----
    e = _validate_str("repositoryId", repositoryId)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    e = _validate_str("branch", branch)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    e = _validate_str("headSha", headSha)
    if e:
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    if source is None:
        source = "github"
    if forceRebuild is None:
        forceRebuild = False

    if not isinstance(source, str) or source not in ["github", "cache", "unknown"]:
        e = _err("VALIDATION_ERROR", "source must be one of: github, cache, unknown")
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e
    if not isinstance(forceRebuild, bool):
        e = _err("VALIDATION_ERROR", "forceRebuild must be a boolean")
        _log_call("VALIDATION_ERROR", e["error"]["message"])
        return e

    # ---- resolve repository ----
    repos = _load("repositories.json")
    if not isinstance(repos, list):
        repos = []
    repo_row = None
    repo_idx = None
    for i, r in enumerate(repos):
        if isinstance(r, dict) and r.get("id") == repositoryId:
            repo_row = r
            repo_idx = i
            break
    if repo_row is None:
        _log_call("NOT_FOUND", "Repository not found", repositoryId=repositoryId)
        return _err("NOT_FOUND", "Repository not found", repositoryId=repositoryId)

    if repo_row.get("status") in ["disabled", "deleted"]:
        _log_call("UNAUTHORIZED", "Repository is not available", repositoryId=repositoryId, repo_status=repo_row.get("status"))
        return _err("UNAUTHORIZED", "Repository is not available", repositoryId=repositoryId)

    # ---- branch resolution ----
    effective_branch = branch
    if effective_branch is None or effective_branch.strip() == "":
        db_default = repo_row.get("default_branch")
        if isinstance(db_default, str) and db_default.strip():
            effective_branch = db_default.strip()
        else:
            # offline resolution: default to main then master fallback (no GitHub check available)
            effective_branch = "main"

    # if defaulted to main but repo default is unknown, we could attempt master fallback heuristically.
    # Without GitHub, we'll allow "main"; callers can pass "master" explicitly.
    if effective_branch not in ["main", "master"] and (effective_branch.strip() == ""):
        effective_branch = "main"

    # ---- head SHA resolution ----
    # Offline: if not provided, derive deterministic pseudo SHA from repo+branch+date to simulate HEAD.
    effective_head_sha = headSha
    if effective_head_sha is None or effective_head_sha.strip() == "":
        seed = f"{repositoryId}:{effective_branch}:{datetime.datetime.utcnow().strftime('%Y-%m-%d')}"
        import hashlib
        effective_head_sha = hashlib.sha1(seed.encode("utf-8")).hexdigest()

    # ---- map tool source -> stored source ----
    stored_source = "unknown"
    if source == "github":
        stored_source = "github_api"
    elif source == "cache":
        # schema has no cache; keep unknown
        stored_source = "unknown"
    else:
        stored_source = "unknown"

    snaps = _load("repo_snapshots.json")
    if not isinstance(snaps, list):
        snaps = []

    # ---- reuse existing ready snapshot when possible ----
    if not forceRebuild:
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("repository_id") == repositoryId and s.get("branch") == effective_branch and s.get("head_sha") == effective_head_sha and s.get("status") == "ready":
                _log_call("OK", "Reused existing ready snapshot", repositoryId=repositoryId, snapshotId=s.get("id"))
                return {"snapshot": s, "reused": True, "effective_branch": effective_branch, "effective_head_sha": effective_head_sha}

    # ---- uniqueness constraint: unique(repository_id, branch, head_sha) ----
    # If a row already exists with same tuple but not ready, return it idempotently (do not claim success without effect).
    for s in snaps:
        if not isinstance(s, dict):
            continue
        if s.get("repository_id") == repositoryId and s.get("branch") == effective_branch and s.get("head_sha") == effective_head_sha:
            # If forceRebuild true, we are supposed to "force a new queued snapshot even if ready exists",
            # but uniqueness constraint forbids a second row with same (repo, branch, sha).
            # Realistic behavior: if same tuple exists, we cannot create another; so return CONFLICT with details.
            if forceRebuild:
                e = _err("CONFLICT", "Snapshot already exists for repository/branch/headSha; cannot create duplicate due to uniqueness constraint",
                         existingSnapshotId=s.get("id"), repositoryId=repositoryId, branch=effective_branch, headSha=effective_head_sha)
                _log_call("CONFLICT", e["error"]["message"])
                return e
            _log_call("OK", "Returned existing snapshot", repositoryId=repositoryId, snapshotId=s.get("id"))
            return {"snapshot": s, "reused": False, "effective_branch": effective_branch, "effective_head_sha": effective_head_sha}

    # ---- create queued snapshot ----
    now = _now_iso()
    snap = {
        "id": _gen_id("rs"),
        "repository_id": repositoryId,
        "branch": effective_branch,
        "head_sha": effective_head_sha,
        "source": stored_source,
        "status": "queued",
        "tree_root_path": "/",
        "tree_node_count": None,
        "total_bytes_indexed": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    snaps.append(snap)
    _save("repo_snapshots.json", snaps)

    _log_call("OK", "Created queued snapshot", repositoryId=repositoryId, snapshotId=snap["id"])
    return {"snapshot": snap, "reused": False, "effective_branch": effective_branch, "effective_head_sha": effective_head_sha}
